import sqlite3

import streamlit as st

import calendar_import
import config
import database
import ui_components


def _welcome():
    """Introduce the problem and the three-step activity flow."""
    st.title('Welcome to WeekWise')
    st.write(config.PROBLEM_STATEMENT)
    st.write('1. Find the free gaps in your calendar.')
    st.write('2. Choose fitting activities and add one date to your calendar.')
    st.write('3. Rate activities afterwards to improve future suggestions.')
    st.caption('Your focus, favorites and ratings help personalize the suggestions.')
    if st.button('Next', type='primary', key='ww_welcome_next'):
        st.session_state['ww_onboarding_step'] = 2
        st.rerun()


def _focus():
    """Collect and validate a display name and at least one focus choice."""
    st.header('Your focus')
    previous = st.session_state.get('ww_onboarding_profile',
                                    {'name': '', 'directions': set(config.DIRECTION_LABELS)})
    name, directions = ui_components.render_profile_fields(
        previous['name'], previous['directions'], 'ww_onboarding')
    history = st.checkbox('Load demo history', value=previous.get('demo_history', True),
                           key='ww_demo_history')
    st.caption('Try ratings and feedback with sample past activities and three demo friends. '
               'You can clear the sample history in Settings.')
    if st.button('Back', key='ww_focus_back'):
        st.session_state['ww_onboarding_profile'] = {
            'name': name, 'directions': directions, 'demo_history': history}
        st.session_state['ww_onboarding_step'] = 1
        st.rerun()
    if st.button('Next', type='primary', key='ww_focus_next'):
        try:
            profile = database.validate_profile(name, directions)
            st.session_state['ww_onboarding_profile'] = {
                'name': profile.display_name, 'directions': profile.directions,
                'demo_history': history}
            st.session_state['ww_onboarding_step'] = 3
            st.rerun()
        except ValueError as error:
            st.error(str(error))


def _use_demo():
    """Choose demo explicitly after a failed private-input test, before widgets rerender."""
    st.session_state['ww_calendar_choice'] = 'demo'
    st.session_state.pop('ww_calendar_test', None)


def _calendar_validation(mode, link, upload, now):
    """Require an unchanged successful link test or a parsed upload before Finish."""
    result = st.session_state.get('ww_calendar_test')
    if mode == 'link':
        if st.button('Test link', key='ww_test_calendar'):
            result = ui_components.test_calendar_input(mode, link, upload, now)
            st.session_state['ww_calendar_test'] = result
    elif mode == 'upload' and upload is not None:
        if result is None or result['input'] != (mode, link, upload):
            result = ui_components.test_calendar_input(mode, link, upload, now)
            st.session_state['ww_calendar_test'] = result
    elif mode == 'demo':
        result = ui_components.test_calendar_input(mode, link, upload, now)
    if result and result['input'] == (mode, link, upload):
        ui_components.show_calendar_test(result)
        if not result['ok']:
            st.button('Use demo calendar', on_click=_use_demo, key='ww_choose_demo')
        return result['ok']
    if mode == 'link':
        st.info('Test your link before finishing, or choose the demo calendar.')
    elif mode == 'upload':
        st.info('Choose an .ics file before finishing.')
    return False


def _finish(connection, mode, link, upload, remember, now):
    """Save validated onboarding choices while keeping private inputs out of the database."""
    # Recheck at the write boundary: an earlier successful test is not a permanent guarantee.
    result = ui_components.test_calendar_input(mode, link, upload, now)
    if not result['ok']:
        st.session_state['ww_calendar_test'] = result
        ui_components.show_calendar_test(result)
        return
    values = st.session_state['ww_onboarding_profile']
    new_input = (mode == 'link' and link is not None) or (mode == 'upload' and upload is not None)
    if remember and new_input:
        calendar_import.remember_calendar(mode, link, upload)
    database.complete_onboarding(connection, values['name'], values['directions'], mode, now,
                                  load_demo_history=values.get('demo_history', True))
    st.session_state['ww_calendar_mode'] = mode
    st.session_state['ww_calendar_link'] = link
    st.session_state['ww_calendar_upload'] = upload
    st.session_state.pop('ww_calendar_test', None)
    ui_components.cached_calendar.clear()
    st.rerun()


def _calendar(connection, now):
    """Show demo/link/upload choices and finish only after source-specific validation."""
    st.header('Your calendar')
    ui_components.initialize_calendar_state(connection)
    mode, link, upload, remember = ui_components.calendar_source_inputs()
    valid = _calendar_validation(mode, link, upload, now)
    if st.button('Back', key='ww_calendar_back'):
        st.session_state['ww_onboarding_step'] = 2
        st.rerun()
    if st.button('Finish', type='primary', disabled=not valid, key='ww_finish_onboarding'):
        _finish(connection, mode, link, upload, remember, now)


def render_onboarding(connection, now=None):
    """Render the three-step welcome flow before exposing the main app navigation."""
    now = config.local_now(now)
    # Course: L04 – session state retains the selected step across widget reruns.
    step = st.session_state.get('ww_onboarding_step', 1)
    st.caption(f'Step {step} of 3')
    if step == 1:
        _welcome()
    elif step == 2:
        _focus()
    else:
        _calendar(connection, now)
    ui_components.render_sidebar_status()


try:
    render_onboarding(ui_components.cached_connection())
except (OSError, ValueError, KeyError, sqlite3.Error):
    st.error('Could not finish setup. Please check your choices and try again.')
